UPDATE eval_case_candidate
SET attribution = #{attribution}, attribution_note = #{note},
    attribution_by = #{by}, attribution_at = #{at}
WHERE id = #{id}

mapper.select:
SELECT 
FROM eval_case_candidate

    attribution IS NOT NULL
    AND attribution_at >= #{startTime}
    AND attribution_at <= #{endTime}
    AND source = #{source}

ORDER BY attribution_at DESC LIMIT #{limit}

SELECT 
FROM eval_case_candidate

    AND source = #{source}
    AND status = #{status}

ORDER BY create_time DESC, id DESC LIMIT #{size} OFFSET #{offset}
